    use super::*;
    use std::sync::mpsc;
    use std::thread;
    use std::time::Duration;

    /// Concurrent awards to the same player must not lose points.
    #[test]
    fn concurrent_awards_keep_every_point() {
        let board = Board::new();
        board.join(1, 0);
        let mut handles = Vec::new();
        for _ in 0..8 {
            let b = board.clone();
            handles.push(thread::spawn(move || {
                for _ in 0..1000 {
                    b.award(1, 1);
