    /// Opposite-direction transfers must not deadlock.
    #[test]
    fn opposite_transfers_do_not_deadlock() {
        let board = Board::new();
        board.join(1, 100);
        board.join(2, 100);
        let (tx, rx) = mpsc::channel();
        let tx1 = tx.clone();
        let b1 = board.clone();
        let t1 = thread::spawn(move || {
            for _ in 0..1000 {
                b1.transfer(1, 2, 1);
            }
            tx1.send(()).unwrap();
        });
        let b2 = board.clone();
        let t2 = thread::spawn(move || {
            for _ in 0..1000 {
                b2.transfer(2, 1, 1);
            }
            tx.send(()).unwrap();
        });
        // Time out instead of hanging forever if the transfers deadlock.
        assert!(rx.recv_timeout(Duration::from_secs(10)).is_ok());
        assert!(rx.recv_timeout(Duration::from_secs(10)).is_ok());
        t1.join().unwrap();
        t2.join().unwrap();
        assert_eq!(board.total(), 200);
        assert_eq!(board.score(1) + board.score(2), 200);
    }

    /// A self-transfer changes nothing (and must not deadlock).
    #[test]
    fn self_transfer_changes_nothing() {
        let board = Board::new();
        board.join(1, 42);
        board.transfer(1, 1, 10);
        assert_eq!(board.score(1), 42);
        assert_eq!(board.total(), 42);
    }
}

