    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        // Read-modify-write while holding the lock so concurrent awards to
        // the same player cannot lose each other's points.
        *self.slot(id).lock().unwrap() += points;
        *self.total.lock().unwrap() += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        if from == to {
            return;
        }
        // Lock the two slots in a canonical order (by PlayerId) so that two
        // threads transferring in opposite directions cannot deadlock.
        let (lo, hi) = if from < to { (from, to) } else { (to, from) };
        let lo_slot = self.slot(lo);
        let hi_slot = self.slot(hi);
        let mut lo_score = lo_slot.lock().unwrap();
        let mut hi_score = hi_slot.lock().unwrap();
        if from < to {
            *lo_score -= points;
            *hi_score += points;
        } else {
            *lo_score += points;
            *hi_score -= points;
        }
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        *self.slot(id).lock().unwrap()
    }

    pub fn total(&self) -> i64 {
        *self.total.lock().unwrap()
    }
}

